double
Pr(int u, double eta)
{
	int l;
	double sum, p;

	if ( u == 0 )
		p = exp(-eta);
	else {
		sum = 0.0;
		for ( l=1; l<=u; l++ )
			sum += log((double)l);
		p = exp(-eta + u*log(eta) - sum);
	}
	return p;
}
```
